-- 0191: aṣl from every book, batch 11 — each book's own statement (read by its profile; Lane in English), verbatim
-- with block + page and a plain English line; primary = the meaning most books share. Quotes checked against blocks.
-- aslmb_11: aṣl per book for 25 roots that rested on Ibn Fāris alone (AGR:VOC:002/017).
-- Each row: the book's own words as printed + block + page + entry. ONE primary per root, by the reading most books share
-- (tie -> the earliest book). Standalone: INSERT OR IGNORE + guarded UPDATEs; safe to re-run. No row deleted.
-- رمز
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:رمز:khalil_kitab_ayn', 'رمز', '7695612f44cb83d0249a3dfbe1', 'والرّمز باللسان: الصّوت الخفيّ. ويكون [الرّمز] : الإيماء بالحاجب بلا كلام', 'a soft sound; a nod of the eyebrow', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_bd95e328942fe40f', '2669', NULL, 'blk_kay_985536008e96ff0a', 0, NULL, 'Marker: head gloss. Reading: silent signal. Primary: silent signal — 8 of 9 books (al-Khalīl blk_kay_985536008e96ff0a; al-Jawharī blk_sih_81473b95df7034f5; al-Rāghib blk_mfr_e15460472a5c8173; Lisān blk_lsn_571de727a8f1b474; al-Miṣbāḥ blk_msb_711d5ba3e27db93e; al-Qāmūs blk_qms_0f1fffb158f639b1; Tāj blk_taj_6fcdb4bc55b9a0c7; Lane blk_lane_8b4dcfd60d83fe87). Other readings: movement and shaking: Ibn Fāris.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:رمز:jawhari_sihah', 'رمز', '7695612f44cb83d0249a3dfbe1', 'الرَمْزُ: الإشارةُ والإيماءُ بالشفَتين والحاجب', 'a sign with the lips and eyebrow', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_20445e39c6a68985', '1741', 3, 'blk_sih_81473b95df7034f5', 0, NULL, 'Marker: head gloss. Reading: silent signal.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:رمز:raghib_mufradat', 'رمز', '7695612f44cb83d0249a3dfbe1', 'الرَّمْزُ: إشارة بالشّفة، والصّوت الخفيّ، والغمز بالحاجب', 'a sign with the lip, a soft sound', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_c85103b2cdb3048c', '366', 1, 'blk_mfr_e15460472a5c8173', 0, NULL, 'Marker: head gloss. Reading: silent signal.', 'high', 'active');
