INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:رهق:fayyumi_misbah_munir', 'رهق', 'cf30d6ccc3dc38ab81964e86fa', 'رَهِقْتُ الشَّيْءَ رَهَقًا مِنْ بَابِ تَعِبَ قَرُبْتُ مِنْهُ', 'I came near it', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_763d5a5b4f1ca569', '1236', NULL, 'blk_msb_3fe83cf12ab24e34', 0, NULL, 'Marker: head gloss. Reading: drawing near.', 'high', 'active');
