INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زبد:lane_lexicon', 'زبد', 'f1c8ff2341d33d2c9212a397ff', 'He fed him with, or gave him to eat, زُبْد [i. e. fresh butter]', 'he fed him fresh butter', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_a84b16bbe28db548', '1208', NULL, 'blk_lane_e2a1da26fcde1ff8', 0, NULL, 'Marker: first sense A1. Reading: butter.', 'medium', 'active');
