INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زبر:khalil_kitab_ayn', 'زبر', 'ae852c7d5469d184d1c3358c00', 'الزَّبْرُ: طيٌّ البِئْر، تقول: زَبَرْتها، أي: طَوَيْتها', 'lining a well with stones', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_03f14f935fe5041d', '2665', NULL, 'blk_kay_9e4344796f21b05a', 0, NULL, 'Marker: head gloss. Reading: lining a well. Primary: making firm, strong — 6 of 10 books (al-Khalīl blk_kay_9e4344796f21b05a; Ibn Fāris blk_mqy_8a29f42aa3aa2936; Lisān blk_lsn_864428daae9654ef; al-Qāmūs blk_qms_36d1f064482aa756; Tāj blk_taj_8cf9f4ea92757f27; Lane blk_lane_24e79e113e158126). Other readings: writing: Ibn Durayd, Ibn Fāris · big lump: al-Jawharī, al-Rāghib · scolding, checking: al-Miṣbāḥ.', 'high', 'active');
