INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زبر:ibn_manzur_lisan_arab', 'زبر', 'ae852c7d5469d184d1c3358c00', 'وأَصلُ الزَّبْرِ: طَيُّ الْبِئْرِ إِذا طُوِيَتْ تَمَاسَكَتْ وَاسْتَحْكَمَتْ', 'lining a well, so it holds firm', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_b70592e9c00ba9d5', '2275', 4, 'blk_lsn_864428daae9654ef', 0, NULL, 'Marker: «وأصل». Reading: lining a well.', 'high', 'active');
