INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زفر:raghib_mufradat', 'زفر', 'e7b57f49197b93d4ac63b998e9', 'فَالزَّفِيرُ: تردّد النّفس حتى تنتفخ الضّلوع منه', 'breath going back and forth till the ribs swell', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_0efeaea2f266f7cc', '380', 1, 'blk_mfr_1e56adf690718c68', 0, NULL, 'Marker: opening definition. Reading: heavy breathing.', 'high', 'active');
