INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زفر:qamus_muhit', 'زفر', 'e7b57f49197b93d4ac63b998e9', 'زَفَرَ، يَزْفِرُ زَفْراً وزَفيراً: أخْرَجَ نَفَسَهُ بعدَ مَدِّه إِيَّاه', 'breathing out after drawing a long breath', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_0df4dc60fe818431', NULL, NULL, 'blk_qms_5d2b023ee488d5e6', 0, NULL, 'Marker: Qāmūs gloss. Reading: breathing out.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زفر:zabidi_taj_arus', 'زفر', 'e7b57f49197b93d4ac63b998e9', '(زَفَرَ يَزْفِر) ، من حَدّ ضَرَبَ، (زَفْراً) ، بالفَتْح، (وَزَفِيراً) ، كأَمِيرٍ: (أَخرَجَ نَفَسَه) مُحَرَّكةً (بعدَ مَدِّه إِياه)', 'breathing out after drawing a long breath', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_ba959ad985185a81', '431', 11, 'blk_taj_9c9d0f7f1621a681', 0, NULL, 'Marker: Qāmūs gloss. Reading: breathing out.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زفر:lane_lexicon', 'زفر', 'e7b57f49197b93d4ac63b998e9', 'it originally signifies he drew back his breath vehemently, so that his ribs became swollen out', 'drawing breath hard till the ribs swell', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_855f4820b9a56248', '1236', NULL, 'blk_lane_31a7a4d3d658d5a7', 0, NULL, 'Marker: originally. Reading: heavy breathing. Quoted from Er-Rāghib via Lane.', 'high', 'active');
