INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زلم:khalil_kitab_ayn', 'زلم', '54419ac164f102de4716e7972b', 'الزُّلَمُ، والزَّلَمُ، وجمعه: أزلام، وهي القِداح التي لا ريش لها', 'arrows without feathers (used to draw lots)', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_c4d76e90771ba2a0', '2673', NULL, 'blk_kay_e586daa45783d998', 0, NULL, 'Marker: head gloss. Reading: lot-drawing arrow. Primary: lot-drawing arrow — 5 of 9 books (al-Khalīl blk_kay_e586daa45783d998; Ibn Durayd blk_jam_1a32f0f5d48ce511; al-Jawharī blk_sih_03a7b70a2fbcbe79; Lisān blk_lsn_55c9427fd2cca92a; al-Miṣbāḥ blk_msb_6a727c3fa7b69101). Other readings: hoof: al-Qāmūs, Tāj · cutting off, paring: Lane · slender and smooth: Ibn Fāris.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زلم:ibn_durayd_jamharat_lugha', 'زلم', '54419ac164f102de4716e7972b', 'الزَّلَم والزُّلَم: الْقدح يُستقسم بِهِ', 'the arrow used to draw lots', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_1a32f0f5d48ce511', 0, NULL, 'Marker: first gloss in group. Reading: lot-drawing arrow.', 'high', 'active');
