INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زمل:khalil_kitab_ayn', 'زمل', 'bbc40d69c40852f4a160289290', 'الدّابّة تَزْمُل في عَدْوها ومشيها زَمالاً، إذا رأيتها تَتَحامَلُ على يَدَيْها بَغْياً ونشاطا', 'an animal leaning on its forelegs, from liveliness', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_e42a88e538e93079', '2674', NULL, 'blk_kay_bae3b83a118e4e6d', 0, NULL, 'Marker: «إذا» head gloss. Reading: lopsided running. Primary: lopsided running — 5 of 9 books (al-Khalīl blk_kay_bae3b83a118e4e6d; Lisān blk_lsn_f1a822feadaf319d; al-Qāmūs blk_qms_49bacc030e790e40; Tāj blk_taj_602945e97c4eb567; Lane blk_lane_bbe2b35f9bf082f8). Other readings: sound: al-Jawharī, Ibn Fāris · wrapping up: al-Rāghib, al-Miṣbāḥ · carrying a load: Ibn Fāris.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زمل:jawhari_sihah', 'زمل', 'bbc40d69c40852f4a160289290', 'الازمل: الصوت', 'sound', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_df8eb76e8c499238', '3405', 4, 'blk_sih_9880717227cb547f', 0, NULL, 'Marker: head gloss. Reading: sound. Differs from the main reading (lopsided running).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زمل:raghib_mufradat', 'زمل', 'bbc40d69c40852f4a160289290', 'الْمُتَزَمِّلُ في ثوبه', 'one wrapped in his garment', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_a0d79459b8d3f582', '383', 1, 'blk_mfr_e0afe132a9f107c6', 0, NULL, 'Marker: opening definition. Reading: wrapping up. Differs from the main reading (lopsided running).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زمل:ibn_manzur_lisan_arab', 'زمل', 'bbc40d69c40852f4a160289290', 'زَمَلَ يَزْمِل ويَزْمُلُ زِمَالًا: عَدَا وأَسْرَعَ مُعْتَمِداً فِي أَحد شِقَّيْه رَافِعًا جَنْبَهُ الْآخَرَ', 'running fast leaning on one side', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_92cb4af82ffa8d44', '414', 1, 'blk_lsn_f1a822feadaf319d', 0, NULL, 'Marker: head gloss. Reading: lopsided running.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زمل:fayyumi_misbah_munir', 'زمل', 'bbc40d69c40852f4a160289290', 'زَمَّلْتُهُ بِثَوْبِهِ تَزْمِيلًا فَتَزَمَّلَ مِثْلُ: لَفَفْتُهُ بِهِ فَتَلَفَّفَ بِهِ', 'wrapping someone in his garment', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_dd4e6cf3be25feff', '1318', NULL, 'blk_msb_1ed500d500ecf983', 0, NULL, 'Marker: head gloss. Reading: wrapping up. Differs from the main reading (lopsided running).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زمل:qamus_muhit', 'زمل', 'bbc40d69c40852f4a160289290', 'زَمَلَ يَزْمِلُ ويَزْمُلُ زِمالاً: عَدا مُعْتَمِداً في أحَدِ شِقَّيْهِ، رافِعاً جَنْبَهُ الآخَرَ', 'running leaning on one side', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_182c91a5cd424828', NULL, NULL, 'blk_qms_49bacc030e790e40', 0, NULL, 'Marker: Qāmūs gloss. Reading: lopsided running.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زمل:zabidi_taj_arus', 'زمل', 'bbc40d69c40852f4a160289290', 'زَمَلَ، يَزْمِلُ، ويَزْمُلُ، مِن حَدَّيْ ضَرَبَ ونَصَرَ، زِمالاً، بالكسرِ: عَدَا، وأَسْرَعَ، مُعْتَمِداً فِي أَحَدِ شِقَّيْهِ', 'running fast leaning on one side', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_c8432c60d8133adf', '135', 29, 'blk_taj_602945e97c4eb567', 0, NULL, 'Marker: Qāmūs gloss. Reading: lopsided running.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زمل:lane_lexicon', 'زمل', 'bbc40d69c40852f4a160289290', 'He ran, (Ḳ, TA,) and went along quickly, (TA,) leaning, or bearing, on one side, raising his other side', 'running quickly leaning on one side', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_131cd27f64d3ceb1', '1252', NULL, 'blk_lane_bbe2b35f9bf082f8', 0, NULL, 'Marker: first sense A1. Reading: lopsided running.', 'high', 'active');
