INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زنم:khalil_kitab_ayn', 'زنم', 'a9321dca00fefc2787284f43a6', 'والزَّنَمَة: اللَّحْمة المُتدلِّية في الحلق', 'the flap of flesh hanging from the throat', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_8c9676ba301b4ef5', '2678', NULL, 'blk_kay_60dd50b517d57f38', 0, NULL, 'Marker: head gloss. Reading: hanging flap. Primary: hanging flap — 5 of 7 books (al-Khalīl blk_kay_60dd50b517d57f38; al-Jawharī blk_sih_ffb47d5643286239; Ibn Fāris blk_mqy_85c3f2afb4ce4cd1; Lisān blk_lsn_9a16a2f8fd5be769; Lane blk_lane_ad787ac032e6975b). Other readings: attached outsider: al-Rāghib, al-Miṣbāḥ.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زنم:jawhari_sihah', 'زنم', 'a9321dca00fefc2787284f43a6', 'والزنمة: شئ يقطع من أذن البعير فيترك معلٌّقاً', 'a piece cut in a camel''s ear, left hanging', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_d5acef0a30669f4a', '3856', 5, 'blk_sih_ffb47d5643286239', 0, NULL, 'Marker: head gloss. Reading: hanging flap.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زنم:raghib_mufradat', 'زنم', 'a9321dca00fefc2787284f43a6', 'الزَّنِيمُ والْمَزَنَّمُ: الزّائد في القوم وليس', 'one added to a people, not really of them', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_5a44fb2d06e64161', '383', 1, 'blk_mfr_7525bad8ecdb5b64', 0, NULL, 'Marker: opening definition. Reading: attached outsider. Differs from the main reading (hanging flap).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زنم:ibn_manzur_lisan_arab', 'زنم', 'a9321dca00fefc2787284f43a6', 'زَنَمَتا الأُذن: هَنَتَانِ تَلِيَانِ الشَّحْمَةَ، وَتُقَابِلَانِ الوَتَرَةَ', 'two small bits of the ear by the lobe', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_e148cef257660e29', '6188', 12, 'blk_lsn_9a16a2f8fd5be769', 0, NULL, 'Marker: head gloss. Reading: ear flaps.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زنم:fayyumi_misbah_munir', 'زنم', 'a9321dca00fefc2787284f43a6', 'رَجُلٌ زَنِيمٌ دَعِيٌّ وَمُزَنَّمٌ بِالْبِنَاءِ لِلْمَفْعُولِ وَهُوَ مُشَبَّهٌ بِزَنَمَةِ الْعَنْزِ وَهِيَ الَّتِي تَتَعَلَّقُ بِأُذُنِهَا', 'a man falsely claiming kin, like a goat''s ear-flap', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_ad679fc1dee3aab6', '1326', NULL, 'blk_msb_33ec8da99498e648', 0, NULL, 'Marker: head gloss. Reading: attached outsider. Differs from the main reading (hanging flap).', 'high', 'active');
