INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهد:khalil_kitab_ayn', 'زهد', 'b871aa2a977ea1b94c6a0451ea', 'ورجلٌ زهيد. وإمرأة زهيدةٌ وهما القليل طُعْمُهما', 'a man or woman who eats little', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_31b129bb4e2fcb2a', '1120', NULL, 'blk_kay_4cbeaf143329280e', 0, NULL, 'Marker: head gloss. Reading: littleness. Differs from the main reading (not wanting, giving up).', 'medium', 'active');
