INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهد:jawhari_sihah', 'زهد', 'b871aa2a977ea1b94c6a0451ea', 'الزَهدُ: خلاف الرَغبة', 'the opposite of wanting', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_c915ca9f26583cb2', '946', 2, 'blk_sih_4b36ad77033b88cb', 0, NULL, 'Marker: head gloss. Reading: not wanting.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهد:raghib_mufradat', 'زهد', 'b871aa2a977ea1b94c6a0451ea', 'الزَّهِيدُ: الشيء القليل، والزَّاهِدُ في الشيء: الرّاغب عنه والرّاضي منه بالزّهيد', 'a small thing; one content with little', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_4b74ff367e72a014', '384', 1, 'blk_mfr_8e61bc81ac0343e9', 0, NULL, 'Marker: opening definition. Reading: littleness. Differs from the main reading (not wanting, giving up).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهد:ibn_manzur_lisan_arab', 'زهد', 'b871aa2a977ea1b94c6a0451ea', 'والزُّهد: ضِدُّ الرَّغْبَةِ وَالْحِرْصِ عَلَى الدُّنْيَا', 'the opposite of craving worldly things', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_6da90444e4b990ab', '1638', 3, 'blk_lsn_38d5a23b49a332ac', 0, NULL, 'Marker: head gloss. Reading: not wanting.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهد:fayyumi_misbah_munir', 'زهد', 'b871aa2a977ea1b94c6a0451ea', 'زَهِدَ فِي الشَّيْءِ وَزَهِدَ عَنْهُ أَيْضًا زُهْدًا وَزَهَادَةً بِمَعْنَى تَرَكَهُ وَأَعْرَضَ عَنْهُ', 'leaving a thing and turning away from it', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_d7c4243849070deb', '1328', NULL, 'blk_msb_74ff9831abf800a9', 0, NULL, 'Marker: head gloss. Reading: giving up.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهد:qamus_muhit', 'زهد', 'b871aa2a977ea1b94c6a0451ea', 'زَهَدَ فيه، كمَنَعَ وسَمِعَ وكَرُمَ، زُهْداً وزَهادَةً أو هي في الدُّنْيا، والزُّهْدُ في الدِّينِ: ضِدُّ رَغِبَ', 'the opposite of wanting', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_b9a045faf04a8c6e', NULL, NULL, 'blk_qms_58ae56b45196c6eb', 0, NULL, 'Marker: Qāmūs gloss. Reading: not wanting.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهد:zabidi_taj_arus', 'زهد', 'b871aa2a977ea1b94c6a0451ea', '(ضدُّ رَغِبَ)', 'the opposite of wanting', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_59851e6ab3dbcd7a', '151', 8, 'blk_taj_857e1544613d87c5', 0, NULL, 'Marker: Qāmūs gloss. Reading: not wanting.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهد:lane_lexicon', 'زهد', 'b871aa2a977ea1b94c6a0451ea', 'He abstained from it; [meaning, from something that would gratify the passions or senses;] relinquished it; forsook it', 'holding back from it, giving it up', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_2e89732ba7870e22', '1260', NULL, 'blk_lane_f85ad2e1e0c56c19', 0, NULL, 'Marker: first sense A1. Reading: giving up.', 'high', 'active');
