INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهر:khalil_kitab_ayn', 'زهر', '504e8cb7bae8c83945b9db1ea5', 'الزَّهْرةُ: نَوْرُ كلِّ نَباتٍ. وزَهرةُ الدّنيا: حُسْنُها وبَهْجَتهُا', 'the blossom of any plant; the world''s beauty', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_2b03a1e7fb07f81d', '1121', NULL, 'blk_kay_f6897ef72651ecc2', 0, NULL, 'Marker: head gloss. Reading: blossom. Primary: blossom — 5 of 8 books (al-Khalīl blk_kay_f6897ef72651ecc2; Lisān blk_lsn_7d9ca713932f16b3; al-Miṣbāḥ blk_msb_ae072b3290889d43; al-Qāmūs blk_qms_d6047dfcaa2ec0b2; Tāj blk_taj_813b5b18de03bd4b). Other readings: brightness, beauty: al-Jawharī, Ibn Fāris, Lane.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهر:jawhari_sihah', 'زهر', '504e8cb7bae8c83945b9db1ea5', 'زَهْرَةُ الدُنْيا بالتسكين: غَضارَتُها وحُسْنُها', 'the freshness and beauty of the world', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_b0c365970e9a8974', '1336', 2, 'blk_sih_0977bf877af5677d', 0, NULL, 'Marker: head gloss. Reading: beauty. Differs from the main reading (blossom).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهر:ibn_manzur_lisan_arab', 'زهر', '504e8cb7bae8c83945b9db1ea5', 'الزَّهْرَةُ: نَوْرُ كُلِّ نَبَاتٍ، وَالْجَمْعُ زَهْرٌ، وَخَصَّ بَعْضُهُمْ بِهِ الأَبيض', 'the blossom of any plant', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_9327874eb4109f01', '2291', 4, 'blk_lsn_7d9ca713932f16b3', 0, NULL, 'Marker: head gloss. Reading: blossom.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهر:fayyumi_misbah_munir', 'زهر', '504e8cb7bae8c83945b9db1ea5', 'وَزَهْرُ النَّبَاتِ نَوْرُهُ الْوَاحِدَةُ زَهْرَةٌ', 'the blossom of plants', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_d7c4243849070deb', '1328', NULL, 'blk_msb_ae072b3290889d43', 0, NULL, 'Marker: head gloss. Reading: blossom.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهر:qamus_muhit', 'زهر', '504e8cb7bae8c83945b9db1ea5', 'الزَّهْرَةُ، ويُحَرَّكُ: النباتُ، ونَوْرُهُ، أو الأَصْفَرُ منه', 'plants, their blossom, or the yellow bloom', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_a49b2eb0d49f33c8', NULL, NULL, 'blk_qms_d6047dfcaa2ec0b2', 0, NULL, 'Marker: Qāmūs gloss. Reading: blossom.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهر:zabidi_taj_arus', 'زهر', '504e8cb7bae8c83945b9db1ea5', '(الزَّهْرَة، ويُحرَّك: النَّباتُ) ، عَن ثَعْلب. قَالَ ابنُ سِيده: (و) أُراه إِنّما يُريد (نَوْره)', 'plants, really meaning their blossom', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_a51abcf3a3e5e066', '473', 11, 'blk_taj_813b5b18de03bd4b', 0, NULL, 'Marker: Qāmūs gloss. Reading: blossom.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهر:lane_lexicon', 'زهر', '504e8cb7bae8c83945b9db1ea5', 'It (a star, TA, and the moon, and a lamp, and the face, Ḳ) shone, or glistened', 'shining, glistening', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_5f03e99fcec65400', '1260', NULL, 'blk_lane_44bc993565b6c80e', 0, NULL, 'Marker: first sense A1. Reading: shining. Differs from the main reading (blossom).', 'high', 'active');
UPDATE ar_ling_root_asl SET note_md = trim(CASE WHEN instr(coalesce(note_md,''),'Primary:') > 0 THEN substr(note_md, 1, instr(note_md,'Primary:') - 1) ELSE coalesce(note_md,'') END) || ' ' || 'Reading: brightness, beauty. Differs from the main reading (blossom).', updated_at = datetime('now') WHERE id = 'ASL:زهر:maqayis_lugha' AND coalesce(note_md,'') NOT LIKE '%Reading:%';
