INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهق:khalil_kitab_ayn', 'زهق', '600999b513006a5f4643d22137', 'زَهَقَتْ نفسُه، وهي تَزْهَقُ زُهُوقاً، أي: ذهبت', 'his soul went out', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_e9f5160358196b9b', '1061', NULL, 'blk_kay_6ffd7e7744fdb838', 0, NULL, 'Marker: head gloss. Reading: soul leaving. Primary: going out, passing away — 6 of 10 books (al-Khalīl blk_kay_6ffd7e7744fdb838; Ibn Durayd blk_jam_331d1ddea56df03a; al-Rāghib blk_mfr_07d081fde74d6776; Lisān blk_lsn_af728d3842e53289; al-Miṣbāḥ blk_msb_559dd867ce22a0d4; Lane blk_lane_43704f720c8cd64a). Other readings: full marrow: al-Jawharī, al-Qāmūs, Tāj · going ahead, passing beyond: Ibn Fāris.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهق:ibn_durayd_jamharat_lugha', 'زهق', '600999b513006a5f4643d22137', 'الزَّهَق من قَوْلهم: زَهِقَتْ نفسُه تزهَق زَهَقاً، وأزهقتُه إزهاقاً. وكل تالِفٍ زاهقٌ', 'soul leaving; anything ruined has zahaqa', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_331d1ddea56df03a', 0, NULL, 'Marker: first gloss in group. Reading: soul leaving.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهق:jawhari_sihah', 'زهق', '600999b513006a5f4643d22137', 'العظمُ زهوقاً، أي اكتنز مخه', 'the bone became full of marrow', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_0622dbfa08cfe2d1', '2954', 4, 'blk_sih_98bba56f114fa235', 0, NULL, 'Marker: head gloss. Reading: full marrow. Differs from the main reading (going out, passing away).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهق:raghib_mufradat', 'زهق', '600999b513006a5f4643d22137', 'زَهَقَتْ نفسه: خرجت من الأسف على الشي', 'his soul went out from grief', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_aebc791e084d467d', '384', 1, 'blk_mfr_07d081fde74d6776', 0, NULL, 'Marker: opening definition. Reading: soul leaving.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهق:ibn_manzur_lisan_arab', 'زهق', '600999b513006a5f4643d22137', 'زهَقَ الشيءُ يَزْهَقُ زُهوقاً، فَهُوَ زاهِقٌ وزَهوقٌ: بطَل وهلَك واضْمَحَلّ', 'came to nothing, perished, faded away', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_626b23af1f3048e5', '4817', 10, 'blk_lsn_af728d3842e53289', 0, NULL, 'Marker: head gloss. Reading: passing away.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهق:fayyumi_misbah_munir', 'زهق', '600999b513006a5f4643d22137', 'زُهُوقًا خَرَجَتْ وَأَزْهَقَهَا اللَّهُ', '(the soul) went out', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_d7c4243849070deb', '1328', NULL, 'blk_msb_559dd867ce22a0d4', 0, NULL, 'Marker: head gloss. Reading: soul leaving.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهق:qamus_muhit', 'زهق', '600999b513006a5f4643d22137', 'زَهَقَ العَظْمُ، كمَنَعَ: زُهوقاً: اكْتَنَزَ مُخُّهُ', 'the bone became full of marrow', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_819627fbf7b5a05f', NULL, NULL, 'blk_qms_869ee875a0ea210c', 0, NULL, 'Marker: Qāmūs gloss. Reading: full marrow. Differs from the main reading (going out, passing away).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهق:zabidi_taj_arus', 'زهق', '600999b513006a5f4643d22137', 'زَهَقَ العَظْمُ، كمنع، زهوُقاً: اكْتَنَزَ مُخه', 'the bone became full of marrow', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_4e0d747741f5c798', '423', 25, 'blk_taj_30f0339d9f0032be', 0, NULL, 'Marker: Qāmūs gloss. Reading: full marrow. Differs from the main reading (going out, passing away).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زهق:lane_lexicon', 'زهق', '600999b513006a5f4643d22137', 'His soul went forth, passed forth, or departed', 'his soul went out, departed', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_69c2f97a9f823e22', '1261', NULL, 'blk_lane_43704f720c8cd64a', 0, NULL, 'Marker: first sense A1. Reading: soul leaving.', 'high', 'active');
