INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زوج:ibn_durayd_jamharat_lugha', 'زوج', '18dea05b7e50a93339bea9b97a', 'وَالزَّوْج: زوج الْمَرْأَة وَالْمَرْأَة زوج الرجل وكل اثْنَيْنِ زوج', 'husband or wife; any two make a pair', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_76de4a5b3c45ab86', '437', NULL, 'blk_jam_f9bb30002b67fb6a', 0, NULL, 'Marker: first gloss in group. Reading: spouse, pair. Differs from the main reading (pair).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زوج:jawhari_sihah', 'زوج', '18dea05b7e50a93339bea9b97a', 'زَوْجُ المرأة: بعلها. وزَوجُ الرجل: امرأته', 'a woman''s husband; a man''s wife', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_d0e63a2dc6f00ca9', '629', 1, 'blk_sih_7be2e4fdec23c204', 0, NULL, 'Marker: head gloss. Reading: spouse. Differs from the main reading (pair).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زوج:raghib_mufradat', 'زوج', '18dea05b7e50a93339bea9b97a', 'يقال لكلّ واحد من القرينين من الذّكر والأنثى في الحيوانات الْمُتَزَاوِجَةُ زَوْجٌ، ولكلّ قرينين فيها وفي غيرها زوج', 'each of a matched male and female pair', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_76ff8a70c7b2b0ec', '384', 1, 'blk_mfr_9db7e3b466548e71', 0, NULL, 'Marker: opening definition. Reading: one of a pair.', 'high', 'active');
