UPDATE ar_ling_root_asl SET note_md = trim(CASE WHEN instr(coalesce(note_md,''),'Primary:') > 0 THEN substr(note_md, 1, instr(note_md,'Primary:') - 1) ELSE coalesce(note_md,'') END) || ' ' || 'Reading: moving away. Primary: moving away — 5 of 7 books (Ibn Fāris blk_mqy_e7375923ab0881a1; Lisān blk_lsn_22dc6140dbd1ae2b; al-Miṣbāḥ blk_msb_183bf53ccf70494d; Tāj blk_taj_cb672b518b0f57a3; Lane blk_lane_5602016e0e1f47fc). Other readings: witty person: Ibn Durayd · marvel: al-Jawharī.', updated_at = datetime('now') WHERE id = 'ASL:زول:maqayis_lugha' AND coalesce(note_md,'') NOT LIKE '%Reading:%';
UPDATE ar_ling_root_asl SET is_primary = CASE WHEN id = 'ASL:زول:maqayis_lugha' THEN 1 ELSE 0 END, updated_at = datetime('now') WHERE root_norm = 'زول' AND EXISTS (SELECT 1 FROM ar_ling_root_asl WHERE id = 'ASL:زول:maqayis_lugha' AND status <> 'rejected');
